  };
  return {
    ...local,
    target: typeof local.target === 'object' && local.target ? clean(local.target) : local.target,
    stagePieces: local.stagePieces.map(clean),
    completed: { daisy: local.completed.daisy },
  };
}
export async function skillDecision(
  run: Run,
  model: string,
  ask: Ask,
  experience: unknown[],
  excludedTarget: string | null = null,
) {
  const view = stageView(semanticFacts(focusedObservation({ ...run, target: null }, run.state)));
  // Offer every piece in the model-selected goal, including completed ones.
  // Only an explicit model recovery decision excludes its previous target.
  const candidates = view.stagePieces.filter((p) => p.piece !== excludedTarget);
  const q: JevRequest['questions'] = {
    target: {
      type: 'choice',
      instructions:
        'Choose one unfinished piece for the current goal. Keep working on previousTarget while its stage goal is incomplete, so setup/staging is followed by insertion/lifting. Change target when the previous one is complete, absent from this stage, or excluded by recovery. When choosing a new target, prefer an accessible piece. Do not choose pieces marked stage goal complete. A solved bottom edge is NOT a complete daisy petal. For top-layer stages select whole.',
      criteria: run.stage.startsWith('top-')
        ? { whole: 'Work on the entire top layer pattern.' }
        : Object.fromEntries(
            candidates.map((p) => [
              p.piece,
              `${p.piece} at ${p.position}; destination ${p.destination}; stage goal ${p.satisfiesStageGoal ? 'complete' : 'incomplete'}.`,
            ]),
          ),
    },
  };
  const ids = run.stage.startsWith('top-') ? ['whole'] : candidates.map((p) => p.piece);
  for (const id of ids)
    q['intent_' + id] = {
      type: 'choice',
      instructions: `Choose the immediate intention for ${id === 'whole' ? 'the top layer' : `the exact record at \`stagePieces[${view.stagePieces.findIndex((p) => p.piece === id)}]\``}. Read its position and stickers, not the position suggested by its permanent piece identifier. ${guidance[run.stage]}`,
      criteria: intentions[run.stage],
    };
  const assessed = await ask({
    model,
    state: {
      ...view,
      previousTarget: candidates.find((p) => p.piece === run.target) ?? null,
      previouslyTriedFromThisState: experience,
    },
    questions: q,
  });
  const target = assessed.answers.target.choice;
  const intent = assessed.answers['intent_' + target].choice;
  if (intent === 'done') throw new Error('Policy abstained: selected completed target');
  const selected = { ...run, target };
  const views = Object.fromEntries(
    ['F', 'R', 'B', 'L'].map((front) => {
      const local = stageView(
        semanticFacts(referenceObservation(focusedObservation(selected, run.state), front)),
      );
      return [front, local];
    }),
  );
  const ref = await ask({
    model,
    state: {
      intent,
      stage: run.stage,
      referenceViews: Object.fromEntries(
        Object.entries(views).map(([f, v]) => [
          f,
          {
            target: v.target,
            whiteUpPositions: (v as any).whiteUpPositions,
            sideRows: (v as any).sideRows,
            centers: v.frame.centers,
            ...(run.stage.startsWith('top-') ? { stagePieces: v.stagePieces } : {}),
          },
        ]),
      ),
    },
    questions: {
      reference: {
        type: 'choice',
        instructions: `Compare referenceViews.F, referenceViews.R, referenceViews.B and referenceViews.L. Choose the view satisfying this reference requirement for the target. This renames coordinates, not a move. ${referenceRules[run.stage]}`,
        criteria: Object.fromEntries(
          ['F', 'R', 'B', 'L'].map((f) => [
            f,
            `Reference ${f}: front center ${views[f].frame.centers.F}; target ${JSON.stringify(views[f].target)}; white-up positions ${JSON.stringify((views[f] as any).whiteUpPositions)}; side rows ${JSON.stringify((views[f] as any).sideRows)}. All subsequent moves use these local coordinates.`,
          ]),
        ),
      },
    },
  });
  const front = ref.answers.reference.choice;
  if (run.stage === 'daisy') {
    const local = views[front];
    const piece =
      typeof local.target === 'object' && local.target
        ? Object.fromEntries(Object.entries(local.target).filter(([k]) => k !== 'piece'))
        : null;
    const petals = local.stagePieces
      .filter((p) => p.stickers.yellow === 'U')
      .map((p) => p.position);
    const lift = await ask({
      model,
      state: { target: piece, yellowUpSlots: petals },
      questions: {
        lift: {
          type: 'choice',
          instructions:
            'Choose the lift/flip whose stated starting POSITION and yellow sticker DIRECTION match target. Ignore occupied landing slots for this question; a separate setup decision will clear them. Do not choose lift-bottom unless target is at DF with yellow pointing D.',
          criteria: { ...skillOptions('daisy'), reconsider: 'No described operation matches.' },
        },
      },
    });
    const selectedLift = lift.answers.lift.choice;
    if (selectedLift === 'reconsider')
      throw new Error('Policy abstained: no matching daisy operation');
    const clearSlots: Record<string, string[]> = {
      'lift-bottom': ['UF'],
      'lift-middle-right': ['UR'],
      'lift-middle-left': ['UL'],
      'flip-bottom-edge': ['UF', 'UL'],
      'stage-bottom-edge': ['UF'],
      'flip-top-edge': ['UR'],
      'flip-top-edge-left': ['UL'],
      'lower-top-edge': [],
    };
    const occupancy = Object.fromEntries(
      ['UF', 'UR', 'UB', 'UL'].map((slot) => [
        slot,
        petals.includes(slot) ? 'occupied by yellow-up petal' : 'free of yellow-up petals',
      ]),
    );
    const preparationState = {
      target: piece,
      topSlotOccupancy: occupancy,
      mustBeFree: clearSlots[selectedLift],
    };
    const preparation = await ask(daisyPreparation(model, preparationState));
    const prep = preparation.answers.preparation.choice;
    const clearance = prep === 'clear' ? await ask(daisyClearance(model, preparationState)) : null;
    const skill =
      prep === 'execute'
        ? selectedLift
        : prep === 'lower'
          ? 'lower-top-edge'
          : clearance!.answers.clearance.choice;
    const alg = mapAlg(skills.find((s) => s.id === skill)?.alg || skill, front);
    return { target, front, skill, alg, intent: prep === 'execute' ? intent : 'clear' };
  }
  const options = {
    ...(intent === 'align' || intent === 'clear' ? {} : skillOptions(run.stage)),
    ...Object.fromEntries(['U', "U'", 'U2'].map((m) => [m, setupDescription(m)])),
    reconsider: 'No suitable action: stop for inspection rather than move arbitrarily.',
  };
  const answer = await ask({
    model,
    state: {
      ...views[front],
      target:
        typeof views[front].target === 'object' && views[front].target
          ? Object.fromEntries(Object.entries(views[front].target).filter(([k]) => k !== 'piece'))
          : views[front].target,
      stagePieces: intent === 'align' ? undefined : views[front].stagePieces,
      chosenIntention: intent,
      previouslyTriedFromThisState: experience,
    },
    questions: {
      operation: {
        type: 'choice',
        instructions: `Execute the chosenIntention, selecting just ONE next setup turn or complete skill. ${intent === 'align' ? (run.stage === 'first-layer' ? 'The target corner must move from target.position to the top slot directly above target.destination. DRF requires UFR; DFL requires ULF; DLB requires UBL; DBR requires URB. Use ONLY local destination, never original piece identity. Read U position cycles in the options.' : run.stage === 'middle-layer' ? 'The reference front center matches the SIDE-facing sticker. Rotate U so the target moves to UF and that sticker faces F. Use the edge-position cycles in the options.' : guidance[run.stage]) : guidance[run.stage]} Avoid repeating an action from this exact state that already failed. A setup need not solve the piece; insertion comes later.`,
        criteria: options,
      },
    },
  });
  const skill = answer.answers.operation.choice;
  if (skill === 'reconsider' || intent === 'done')
    throw new Error('Policy abstained: no suitable operation or target already complete');
  const alg = mapAlg(skills.find((s) => s.id === skill)?.alg || skill, front);
  return { target, front, skill, alg, intent };
}

src/server/cross-intention.ts:
import type { Ask } from './skill-policy';
import type { JevRequest } from '../lib/types';
export function crossPhaseRequest(model: string, target: any): JevRequest {
  return {
    model,
    state: {
      alreadySolved: target.solved,
      currentPosition: target.position,
      yellowStickerDirection: target.stickers.yellow,
    },
    questions: {
      phase: {
        type: 'choice',
        instructions:
          'Classify the CURRENT yellow edge for solving the yellow bottom cross. Check alreadySolved first. If already solved choose done. Otherwise, only a yellow sticker pointing U is ready to transfer toward the bottom. Any other yellow direction requires lifting/reorientation first. Do not plan alignment in this question.',
        criteria: {
          done: 'alreadySolved is true',
          extract:
            'Not solved, and yellowStickerDirection is D, F, R, B, or L: lift/reorient first',
          transfer: 'Not solved, and yellowStickerDirection is U: ready to align/transfer',
        },
      },
    },
  };
}
export function crossAlignmentRequest(model: string, target: any): JevRequest {
  return {
    model,
    state: {
      currentPosition: target.position,
      requiredPosition: 'U' + target.destination.slice(1),
    },
    questions: {
      alignment: {
        type: 'choice',
        instructions:
          'The yellow edge has already been classified by the model as ready to transfer. Compare the two position labels exactly. If currentPosition and requiredPosition are IDENTICAL choose insert. If they are DIFFERENT choose align. requiredPosition is the top slot geometrically above the bottom destination; it does not say whether the target is there.',
        criteria: {
          align: 'The two position labels are different',
          insert: 'The two position labels are identical',
        },
      },
    },
  };
}
export async function decideCrossIntention(model: string, target: any, ask: Ask) {
  const phase = await ask(crossPhaseRequest(model, target));
  const choice = phase.answers.phase.choice;
  // These branches route model-selected phases; they do not inspect the cube.
  if (choice === 'transfer')
    return (await ask(crossAlignmentRequest(model, target))).answers.alignment;
  return phase.answers.phase;
}

src/server/goal-policy.ts:
import { colors, facts, goals, pieces } from '../lib/cube';
import type { CubeData, JevRequest } from '../lib/types';

// This reference is identical for every position. The model applies it; code does
// not choose, filter, rank, or simulate candidate goals.
export const STRATEGY_VERSION = 'goal-reference-v2';
export const strategyReference = {
  objective:
    'Solve every piece with its stickers matching the fixed centers. Yellow D first, white U last.',
  progression:
    'A beginner route is daisy → yellow cross → yellow corners → middle edges → white cross → white corner orientation → corner placement → edge placement. Skip goals already achieved. Inspect prerequisites as well as the desired pattern: a white cross alone does not mean the lower layers are solved.',
  daisy:
    'A daisy is a temporary scaffold: four yellow-up edges around the white U center. Build it when starting the yellow edges. Once complete, transfer its petals to the yellow D cross. During transfer the daisy shrinks intentionally: continue cross rather than rebuilding petals. If a yellow cross already exists, do not dismantle it to make a daisy.',
  preservation:
    'Protect completed lower layers. A setup or partial operation can temporarily disturb a pattern; use previousGoal and recentActions to maintain a coherent plan. Change goal when its purpose is achieved or you decide the strategy needs repair. The previous goal is your earlier decision, not a command from code.',
  definitions:
    'completed.topOriented describes white CORNERS only. completed.cornersPlaced checks corner locations, not sticker orientation. These facts are not recommended next actions. Choose orientation before permutation when needed. Finish by aligning the top with its side centers.',
};

export function goalObservation(state: CubeData, previousGoal: string | null, history: string[]) {
  const all = pieces(state);
  return {
    frame: {
      centers: colors,
      note: 'Fixed logical directions; camera position does not affect them. Face stickers are indexed by cube positions.',
    },
    faces: Object.fromEntries(
      Object.entries(colors).map(([face, center]) => [
        face,
        {
          center,
          stickers: Object.fromEntries(
            all
              .filter((p) => p.position.includes(face))
              .map((p) => [
                p.position,
                Object.entries(p.stickers).find(([, direction]) => direction === face)![0],
              ]),
          ),
        },
      ]),
    ),
    completed: facts(state),
    layerMeasurements: {
      yellowCrossEdgesCorrect: all.filter(
        (p) => p.kind === 'edge' && p.destination.includes('D') && p.solved,
      ).length,
      yellowCornersCorrect: all.filter(
        (p) => p.kind === 'corner' && p.destination.includes('D') && p.solved,
      ).length,
      middleEdgesCorrect: all.filter(
        (p) => p.kind === 'edge' && !/[UD]/.test(p.destination) && p.solved,
      ).length,
      whiteEdgesFacingUp: all.filter((p) => p.kind === 'edge' && p.stickers.white === 'U').length,
      whiteCornersFacingUp: all.filter((p) => p.kind === 'corner' && p.stickers.white === 'U')
        .length,
      topCornersAtHome: all.filter(
        (p) => p.kind === 'corner' && p.destination.includes('U') && p.position === p.destination,
      ).length,
      note: 'Each count is out of four. firstLayer=true means ALL yellow edges AND yellow corners are already solved. middle=true means both lower layers are solved.',
    },
    yellowEdges: all
      .filter((p) => p.kind === 'edge' && 'yellow' in p.stickers)
      .map((p) => ({
        position: p.position,
        yellowDirection: p.stickers.yellow,
        destination: p.destination,
        solved: p.solved,
      })),
    previousGoal,
    recentActions: history.slice(-6),
  };
}

export function goalRequest(
  model: string,
  state: CubeData,
  previousGoal: string | null,
  history: string[],
): JevRequest {
  return {
    model,
    state: goalObservation(state, previousGoal, history),
    questions: {
      goal: {
        type: 'choice',
        instructions: {
          task: 'Choose the next goal yourself from the observed cube. Use the strategy reference and recent work to decide whether to continue or change goal. All goals are offered; none has been selected or recommended by the program. Do not choose a completed goal merely because its pattern looks familiar.',
          referenceVersion: STRATEGY_VERSION,
          strategyReference,
        },
        criteria: {
          daisy:
            goals.daisy +
            ' Use as the starting scaffold when the yellow cross is incomplete; not after a completed daisy is being transferred down.',
          cross:
            goals.cross +
            ' Use to transfer a complete daisy, continue its partial transfer, or pursue direct yellow-edge insertion. Skip when completed.cross=true.',
          'first-layer':
            goals['first-layer'] +
            ' Yellow cross must exist and yellow corners must still need work. Skip when completed.firstLayer=true.',
          'middle-layer':
            goals['middle-layer'] +
            ' Choose when yellow bottom edges AND corners are solved but middle edges are not: firstLayer=true, middle=false.',
          'top-cross':
            goals['top-cross'] +
            ' Both lower layers must be solved; white top edges still need orientation.',
          'top-orientation':
            goals['top-orientation'] +
            ' Both lower layers and white top edges must be solved/oriented; white corners still need orientation.',
          'top-corners':
            goals['top-corners'] +
            ' Both lower layers and the white face must be complete; top corners still need placement or alignment.',
          'top-edges':
            goals['top-edges'] +
            ' Lower layers and white orientation must be complete; finish edge permutation after corner placement, or final U alignment.',
        },
      },
    },
  };
}

src/server/jev.ts:
import { readFileSync } from 'node:fs';
import { z } from 'zod';
import { CAP, PRICE, db, event, getRun, reserve, saveRun, settle, spend } from './store';
import { LIMITS, type JevRequest, type JevResponse, type Decision } from '../lib/types';
export const MODEL = 'jev-1.13.0';
function apiKey() {
  if (process.env.TYPESAFE_API_KEY) return process.env.TYPESAFE_API_KEY;
  try {
    const text = readFileSync('/home/frtn/work/2026/laya/.env', 'utf8');
    const line = text.split('\n').find((l) => /^TYPESAFE_API_KEY=/.test(l));
    return line
      ?.slice(line.indexOf('=') + 1)
      .trim()
      .replace(/^['"]|['"]$/g, '');
  } catch {
    return undefined;
  }
}
export function configured() {
  return Boolean(apiKey());
}
const answer = z.object({
  type: z.literal('choice'),
  choice: z.string(),
  probabilities: z.record(z.string(), z.number().min(0).max(1)),
  confidence: z.number().min(0).max(1),
});
const response = z.object({
  model: z.literal(MODEL),
  answers: z.record(z.string(), answer),
  usage: z.object({
    input_tokens: z.number().int().min(0).max(64000),
    output_tokens: z.number().int().nonnegative(),
  }),
});
export function validateResponse(raw: unknown, request: JevRequest): JevResponse {
  const r = response.parse(raw);
  for (const [id, q] of Object.entries(request.questions)) {
    const a = r.answers[id];
    if (
      !a ||
      !(a.choice in q.criteria) ||
      Object.keys(q.criteria).sort().join('|') !== Object.keys(a.probabilities).sort().join('|') ||
      Math.abs(Object.values(a.probabilities).reduce((a, b) => a + b, 0) - 1) > 0.025
    )
      throw new Error('Invalid JEV distribution');
  }
  return r;
}
export async function evaluate(
  runId: string,
  request: JevRequest,
  signal: AbortSignal,
  options: { maxAttempts?: number } = {},
): Promise<Decision> {
  const maxAttempts = options.maxAttempts ?? 3;
  if (!Number.isInteger(maxAttempts) || maxAttempts < 1 || maxAttempts > 3)
    throw new Error('maxAttempts must be between 1 and 3');
  const key = apiKey();
  if (!key) throw new Error('Missing TYPESAFE_API_KEY');
  const body = JSON.stringify(request);
  // Reserve the entire documented 64k request ceiling for every network attempt.
  const reservation = 64000 * PRICE;
  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    signal.throwIfAborted();
    const run = getRun(runId);
    if (run.requests >= LIMITS.requests) throw new Error('Request limit reached');
    const id = crypto.randomUUID();
    db.transaction(() => {
      reserve(id, runId, reservation);
      const current = getRun(runId);
      if (current.requests >= LIMITS.requests) throw new Error('Request limit reached');
      current.requests++;
      saveRun(current);
      event(runId, 'request', { id, attempt, request, reservation });
    }).immediate();
    const start = performance.now();
    let http: Response;
    try {
      http = await fetch('https://api.typesafe.ai/v1/systemone', {
        method: 'POST',
        headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
        body,
        signal: AbortSignal.any([signal, AbortSignal.timeout(30000)]),
      });
    } catch {
      event(runId, 'request-error', {
        id,
        error: 'Network failure or cancellation; reservation retained',
      });
      throw new Error(signal.aborted ? 'Execution cancelled' : 'JEV network timeout/failure');
    }
    if (!http.ok) {
      const text = (await http.text()).replaceAll(key, '[redacted credential]');
      let raw: unknown = text;
      try {
        raw = JSON.parse(text);
      } catch {}
      event(runId, 'request-error', {
        id,
        status: http.status,
        raw,
        error: 'Reservation retained',
      });
      if ([429, 529].includes(http.status) && attempt + 1 < maxAttempts) {
        const retry = Math.min(
          10000,
          Math.max(1000 * 2 ** attempt, Number(http.headers.get('retry-after') || 0) * 1000),
        );
        await new Promise<void>((resolve, reject) => {
          const timer = setTimeout(resolve, retry);
          signal.addEventListener(
            'abort',
            () => {
              clearTimeout(timer);
              reject(new Error('Execution cancelled'));
            },
            { once: true },
          );
        });
        continue;
      }
      throw new Error(`JEV HTTP ${http.status}`);
    }
    const responseText = (await http.text()).replaceAll(key, '[redacted credential]');
    let raw: unknown;
    try {
      raw = JSON.parse(responseText);
    } catch {
      event(runId, 'invalid-response', { id, raw: responseText });
      throw new Error('Malformed JEV JSON; reservation retained');
    }
    let result: JevResponse;
    try {
      result = validateResponse(raw, request);
    } catch {
      event(runId, 'invalid-response', { id, raw });
      throw new Error('Malformed JEV response; reservation retained');
    }
    const cost = result.usage.input_tokens * PRICE;
    const decision = {
      id,
      request,
      response: result,
      nativeResponse: raw,
      elapsedMs: performance.now() - start,
      cost,
    };
    db.transaction(() => {
      settle(id, cost);
      const latest = getRun(runId);
      latest.tokens += result.usage.input_tokens;
      latest.cost += cost;
      saveRun(latest);
      event(runId, 'decision', decision);
    }).immediate();
    return decision;
  }
  throw new Error('JEV retries exhausted');
}
export function budget() {
  const totals = db
    .query(
      "SELECT COALESCE(SUM(CASE WHEN status='settled' THEN amount ELSE 0 END),0) usage,COALESCE(SUM(CASE WHEN status='reserved' THEN amount ELSE 0 END),0) reserved,COUNT(*) attempts FROM ledger",
    )
    .get() as { usage: number; reserved: number; attempts: number };
  return {
    cap: CAP,
    reservedAndSpent: totals.usage + totals.reserved,
    usage: totals.usage,
    reserved: totals.reserved,
    attempts: totals.attempts,
    pricePerMillion: PRICE * 1e6,
    configured: configured(),
  };
}

src/lib/cube.ts:
import { cube3x3x3 } from 'cubing/puzzles';
import { KPattern } from 'cubing/kpuzzle';
import { Alg } from 'cubing/alg';
import type { CubeData } from './types';
export const names = {
  EDGES: 'UF UR UB UL DF DR DB DL FR FL BR BL'.split(' '),
  CORNERS: 'UFR URB UBL ULF DRF DFL DLB DBR'.split(' '),
};
export const colors: Record<string, string> = {
  U: 'white',
  D: 'yellow',
  F: 'green',
  B: 'blue',
  R: 'red',
  L: 'orange',
};
export const turns = 'U D F B R L'.split(' ').flatMap((f) => [f, f + "'", f + '2']);
const puzzle = cube3x3x3.kpuzzle();
export async function solved() {
  return structuredClone((await puzzle).defaultPattern().patternData) as CubeData;
}
export async function apply(state: CubeData, alg: string) {
  return new KPattern(await puzzle, state).applyAlg(alg).patternData as CubeData;
}
export function inverse(alg: string) {
  return new Alg(alg)
    .invert()
    .toString()
    .replace(/([UDFBRL])2'/g, (_, f) => f + '2');
}
export function parseScramble(text: string) {
  const a = text.trim().split(/\s+/).filter(Boolean);
  if (a.length > 100 || a.some((x) => !turns.includes(x)))
    throw new Error("Use at most 100 standard face turns, e.g. R U R' U'.");
  return a.join(' ');
}
export function hash(state: CubeData) {
  return JSON.stringify([state.EDGES, state.CORNERS]);
}
export function isSolved(state: CubeData) {
  return ['EDGES', 'CORNERS'].every((o) =>
    state[o].pieces.every((p, i) => p === i && state[o].orientation[i] === 0),
  );
}
export function pieces(state: CubeData) {
  return Object.entries(names).flatMap(([orbit, slots]) =>
    slots.map((position, i) => {
      const home = slots[state[orbit].pieces[i]];
      const orientation = state[orbit].orientation[i];
      return {
        piece: home,
        kind: orbit === 'EDGES' ? 'edge' : 'corner',
        position,
        destination: home,
        stickers: Object.fromEntries(
          [...home].map((face, j) => [
            colors[face],
            position[(j - orientation + home.length) % home.length],
          ]),
        ),
        solved: home === position && orientation === 0,
      };
    }),
  );
}
export function facts(s: CubeData) {
  const correct = (o: string, start: number, end: number) =>
    s[o].pieces
      .slice(start, end)
      .every((p, j) => p === start + j && s[o].orientation[start + j] === 0);
  return {
    daisy: pieces(s).filter(
      (p) => p.kind === 'edge' && p.position.includes('U') && p.stickers.yellow === 'U',
    ).length,
    cross: correct('EDGES', 4, 8),
    firstLayer: correct('EDGES', 4, 8) && correct('CORNERS', 4, 8),
    middle: correct('EDGES', 4, 12) && correct('CORNERS', 4, 8),
    topCross: s.EDGES.pieces.slice(0, 4).every((p, i) => p < 4 && s.EDGES.orientation[i] === 0),
    topOriented: s.CORNERS.pieces
      .slice(0, 4)
      .every((p, i) => p < 4 && s.CORNERS.orientation[i] === 0),
    cornersPlaced: s.CORNERS.pieces.every((p, i) => p === i),
    solved: isSolved(s),
    solvedPieces: pieces(s).filter((p) => p.solved).length,
  };
}
// Legacy curriculum classifier, retained only for historical fixtures.
// The solving runner must use JEV goal selection instead.
export function stage(s: CubeData, previous?: string) {
  const f = facts(s);
  return !f.cross
    ? previous === 'cross' || f.daisy === 4
      ? 'cross'
      : 'daisy'
    : !f.firstLayer
      ? 'first-layer'
      : !f.middle
        ? 'middle-layer'
        : !f.topCross
          ? 'top-cross'
          : !f.topOriented
            ? 'top-orientation'
            : !f.cornersPlaced
              ? 'top-corners'
              : !f.solved
                ? 'top-edges'
                : 'solved';
}
export const goals: Record<string, string> = {
  daisy:
    'Put all four yellow edges around the white U center, with yellow stickers pointing U. These are petals. Preserve existing petals. Side colors do not need to match centers yet; already solved D edges may be moved to build the daisy.',
  cross:
    'Solve the four yellow edges on D with side colors matching centers. You may use a daisy on U or insert directly.',
  'first-layer': 'Solve yellow corners on D while preserving the yellow cross.',
  'middle-layer':
    'Insert the four edges without white or yellow into the middle layer; preserve D.',
  'top-cross': 'Orient white edge stickers toward U, preserving both lower layers.',
  'top-orientation':
    'Orient all white corner stickers toward U, preserving the lower layers and top cross.',
  'top-corners': 'Position the oriented top corners in their correct destinations.',
  'top-edges': 'Permute the top edges and align U to finish.',
  solved: 'Cube solved.',
};
// Reference yaw is a notation mapping only; it never changes the authoritative frame.
export function mapAlg(alg: string, front: string) {
  const ring = ['F', 'R', 'B', 'L'];
  const offset = ring.indexOf(front);
  if (offset < 0) throw new Error('Invalid reference front');
  return alg
    .split(/\s+/)
    .filter(Boolean)
    .map((m) => {
      const i = ring.indexOf(m[0]);
      return (i < 0 ? m[0] : ring[(i + offset) % 4]) + m.slice(1);
    })
    .join(' ');
}
// Static mechanics reference, independent of the current cube and goal.
const faceCycles: Record<string, string[]> = {
  R: ['U', 'B', 'D', 'F'],
  L: ['U', 'F', 'D', 'B'],
  U: ['F', 'L', 'B', 'R'],
  D: ['F', 'R', 'B', 'L'],
  F: ['U', 'R', 'D', 'L'],
  B: ['U', 'L', 'D', 'R'],
};
export function turnDescription(move: string) {
  const cycle = faceCycles[move[0]];
  const amount = move.endsWith('2') ? 2 : move.endsWith("'") ? 3 : 1;
  return `Turn ${move[0]} ${amount === 1 ? 'clockwise' : amount === 3 ? 'counterclockwise' : '180 degrees'} looking at that face. Only pieces touching ${move[0]} move. Their sticker directions change: ${cycle.map((f, i) => `${f}→${cycle[(i + amount) % 4]}`).join(', ')}; the ${move[0]} sticker direction stays fixed.`;
}
export function targetNames(stageName: string) {
  if (stageName === 'cross' || stageName === 'daisy') return names.EDGES.slice(4, 8);
  if (stageName === 'first-layer') return names.CORNERS.slice(4, 8);
  if (stageName === 'middle-layer') return names.EDGES.slice(8);
  if (stageName === 'top-cross' || stageName === 'top-edges') return names.EDGES.slice(0, 4);
  return names.CORNERS.slice(0, 4);
}
export function stageProgress(state: CubeData, stageName: string) {
  const relevant = pieces(state).filter((p) => targetNames(stageName).includes(p.piece));
  if (stageName === 'daisy') return relevant.filter((p) => p.stickers.yellow === 'U').length;
  if (stageName === 'top-cross' || stageName === 'top-orientation')
    return relevant.filter((p) => p.stickers.white === 'U').length;
  if (stageName === 'top-corners')
    return relevant.filter((p) => p.position === p.destination).length;
  return relevant.filter((p) => p.solved).length;
}
export function focusedObservation(
  r: { state: CubeData; target: string | null; stage: string; history: string[] },
  state = r.state,
) {
  const all = pieces(state),
    target = all.find((p) => p.piece === r.target);
  return {
    frame: {
      centers: colors,
      note: 'Fixed frame. Yellow D first; white U last. Clockwise is viewed directly at the turned face.',
    },
    stage: r.stage,
    goal: goals[r.stage],
    target: target
      ? {
          ...target,
          requiredStickerDirections:
            r.stage === 'daisy'
              ? { yellow: 'U' }
              : r.stage === 'top-cross' || r.stage === 'top-orientation'
                ? { white: 'U' }
                : Object.fromEntries([...target.destination].map((f) => [colors[f], f])),
        }
      : r.target,
    stagePieces: all
      .filter((p) => targetNames(r.stage).includes(p.piece))
      .map((p) => ({
        ...p,
        satisfiesStageGoal: r.stage === 'daisy' ? p.stickers.yellow === 'U' : p.solved,
      })),
    otherPieces: all
      .filter((p) => !targetNames(r.stage).includes(p.piece))
      .map((p) => ({
        piece: p.piece,
        position: p.position,
        stickers: p.stickers,
        solved: p.solved,
      })),
    completed: facts(state),
    recentActions: r.history.slice(-6),
  };
}
export function referenceObservation(
  observation: ReturnType<typeof focusedObservation>,
  front: string,
) {
  const ring = ['F', 'R', 'B', 'L'],
    offset = ring.indexOf(front);
  if (offset < 0) throw new Error('Invalid reference front');
  const face = (f: string) => (ring.includes(f) ? ring[(ring.indexOf(f) - offset + 4) % 4] : f);
  const position = (s: string) => {
    const faces = [...s].map(face);
    return (
      [...names.EDGES, ...names.CORNERS].find(
        (n) => n.length === faces.length && [...n].every((f) => faces.includes(f)),
      ) || faces.join('')
    );
  };
  const transform = (p: any) => ({
    ...p,
    position: position(p.position),
    ...(p.destination ? { destination: position(p.destination) } : {}),
    stickers: Object.fromEntries(
      Object.entries(p.stickers).map(([color, f]) => [color, face(f as string)]),
    ),
    ...(p.requiredStickerDirections
      ? {
          requiredStickerDirections: Object.fromEntries(
            Object.entries(p.requiredStickerDirections).map(([color, f]) => [
              color,
              face(f as string),
            ]),
          ),
        }
      : {}),
  });
  return {
    ...observation,
    frame: {
      centers: Object.fromEntries(Object.entries(colors).map(([f, c]) => [face(f), c])),
      note: `All positions, sticker directions, and algorithm notation in this question use a reference with original ${front} as F. U and D are unchanged. Piece IDs remain permanent identities.`,
    },
    target:
      typeof observation.target === 'object' && observation.target
        ? transform(observation.target)
        : observation.target,
    stagePieces: observation.stagePieces.map(transform),
    otherPieces: observation.otherPieces.map(transform),
    recentActions: observation.recentActions.map((a) =>
      a
        .split(' ')
        .map((m) => face(m[0]) + m.slice(1))
        .join(' '),
    ),
  };
}
export function setupDescription(move: string) {
  if (move === 'none') return 'Do not turn U; every piece stays where it is.';
  const cycle = ['UFR', 'ULF', 'UBL', 'URB'];
  const edges = ['UF', 'UL', 'UB', 'UR'];
  const n = move === 'U' ? 1 : move === 'U2' ? 2 : 3;
  return `${turnDescription(move)} Corner positions: ${cycle.map((s, i) => `${s}→${cycle[(i + n) % 4]}`).join(', ')}. Edge positions: ${edges.map((s, i) => `${s}→${edges[(i + n) % 4]}`).join(', ')}.`;
}
const faceWords: Record<string, string> = {
  U: 'top',
  D: 'bottom',
  F: 'front',
  B: 'back',
  R: 'right',
  L: 'left',
};
export function semanticFacts(view: ReturnType<typeof focusedObservation>) {
  const describe = (p: any) => {
    const targetSides = [...(p.destination || '')]
      .filter((f) => f !== 'U' && f !== 'D')
      .sort()
      .join('');
    const currentSides = [...p.position]
      .filter((f) => f !== 'U' && f !== 'D')
      .sort()
      .join('');
    return {
      ...p,
      topStickerColor: Object.entries(p.stickers).find(([, f]) => f === 'U')?.[0] ?? null,
      sideFacingStickers: Object.entries(p.stickers)
        .filter(([, f]) => !['U', 'D'].includes(f as string))
        .map(([color, direction]) => ({ color, direction })),
      locationWords: [...p.position].map((f) => faceWords[f]).join(' '),
      ...(p.destination
        ? { destinationWords: [...p.destination].map((f) => faceWords[f]).join(' ') }
        : {}),
      layer: p.position.includes('U') ? 'top' : p.position.includes('D') ? 'bottom' : 'middle',
      stickerDirectionsInWords: Object.fromEntries(
        Object.entries(p.stickers).map(([c, f]) => [c, faceWords[f as string]]),
      ),
      directlyAboveHome:
        p.position.includes('U') && p.destination?.includes('D') && currentSides === targetSides,
      sideStickersMatchingCenters: Object.entries(p.stickers)
        .filter(
          ([color, face]) =>
            !['U', 'D'].includes(face as string) && view.frame.centers[face as string] === color,
        )
        .map(([color]) => color),
    };
  };
  return {
    ...view,
    target: typeof view.target === 'object' && view.target ? describe(view.target) : view.target,
    stagePieces: view.stagePieces.map(describe),
  };
}

